/**
 * Grammatical replacement for the RULES_SPEC disabledReason template (DESIGN_REVIEW F-10).
 * `remainingLegs` = legs after the current one (3 - legIndex).
 */
export function formatStaminaDisabledReason(cost: number, stamina: number, remainingLegs: number): string {
  if (stamina < cost) return `Needs ${cost} stamina. You have ${stamina}.`;
  const ahead = remainingLegs === 1 ? 'the final leg' : `the ${remainingLegs} legs ahead`;
  return `Needs ${cost} stamina, but you must keep ${remainingLegs} for ${ahead}.`;
}
